class IntConverter:
    """Convert string to integer with auto base detection from prefix."""
    def __init__(self, base=None):
        self.base = base

    def __call__(self, string, match):
        # R6: Support hex, binary, octal with optional base argument
        # Auto-detect base from prefix (only recognize the correct prefix for each base)
        base = self.base if self.base is not None else 10

        if base == 2:
            prefix_chars = 'bB'
        elif base == 8:
            prefix_chars = 'oO'
        elif base == 16:
            prefix_chars = 'xX'
        else:
            prefix_chars = ''

        # Check for signed prefix like +-0x or +-0b etc
        if len(string) > 2 and string[0] in '+-' and string[2] == '0':
            rest = string[2]
            if rest in prefix_chars:
                base = {**{2:2, 8:8, 16:16}, 'b':2, 'B':2, 'o':8, 'O':8, 'x':16, 'X':16}[rest]
                s = string[3:]
                sign = -1 if string.startswith('-') else 1
                return sign * int(s, base)
            elif string[2] in '+-':
                # Double sign like +0x...
                pass
        elif len(string) > 1 and string[0] == '0':
            rest = string[1]
            if rest in prefix_chars:
                s = string[2:]
                sign = 1
                return sign * int(s, base)

